effect.shader:
void main(){
    vec2 p=acScreenNorm*2.0-1.0; float asp=acScreenSize.x/acScreenSize.y; p.x*=asp;
    float r=length(p);
    if(r>1.0){gl_FragColor=texture2DCv(inputImg.texture, acScreenNorm);return;}
    float maxT=radians(fov)*0.5;
    float theta=r*maxT;
    float rr=sin(theta)/sin(maxT);
    vec2 dir = r>0.0001? p/r : vec2(0.0);
    vec2 np=dir*rr; np.x/=asp;
    vec2 uv=mix(acScreenNorm, np*0.5+0.5, amount);
    gl_FragColor=texture2DCv(inputImg.texture, clamp(uv,0.0,1.0));
}
